<template><view class="word-preview quick-import-page"><view class="word-preview-content"><view class="practice-top import-top"><button class="icon-button back-control" hover-class="none" @click="$emit('close')" :disabled="saving" aria-label="返回 / Retour"><Icon name="back"/></button><Bi zh="导入单词" fr="Importer des mots"/></view><view class="quick-import-body"><text class="muted">用逗号隔开 · Séparez les mots par des virgules.</text><textarea auto-height v-model="input" :adjust-position="false" class="quick-import-input" maxlength="12000" placeholder="bonjour, un livre, hôtel" :disabled="loading||saving"/><button class="button secondary" :disabled="!input.trim()||loading||saving" @click="lookup"><Icon name="search"/><Bi :zh="loading?'正在导入':'导入单词'" :fr="loading?'Importation…':'Importer'" small/></button><view v-if="importedNotice" class="import-success" role="status"><Icon name="check"/><Bi :zh="importedLabel" :fr="importedLabelFr" small/></view><text v-if="error" class="quick-import-error" role="alert">{{ error }}</text><view v-if="results.length" class="quick-import-results"><view v-for="(row,i) in results" :key="i" class="glass quick-import-row"><text>{{ row.input }}</text><view v-if="row.missing" class="missing-word"><Bi zh="未找到，可修改输入后重试" fr="Mot introuvable : corrigez puis réessayez" small/><button class="text-button" @click="results.splice(i,1)"><Bi zh="跳过" fr="Ignorer" small/></button></view><button v-for="option in row.options" :key="option.id" hover-class="none" :class="['quick-word-choice',{selected:row.selected===option.id}]" @click="row.selected=row.selected===option.id?'':option.id"><view><text lang="fr">{{ option.word }}</text><text class="quick-word-pronunciation">{{ option.pos }} {{ option.gender==='m'?'m.':option.gender==='f'?'f.':'' }} {{ option.ipa }}</text><text class="muted">{{ option.meanings.join('；') }}</text><text v-if="!option.example?.fr" class="quick-word-pending">例句待补 · Phrase à compléter</text></view><Icon :name="row.selected===option.id?'check':'plus'"/></button><text v-if="row.options.length>1&&!row.selected" class="muted">请选择一个词 · Choisissez un mot.</text></view></view></view><ConjugationOptions v-if="selected.some(e=>e.pos==='v.'&&isIrregularLemma(e.word))" v-model="conjugationPlan"/><view v-if="results.length&&selected.length" class="exercise-footer"><button class="button primary wide" hover-class="none" :disabled="!selected.length||saving||loading" @click="submit"><Icon name="upload"/><Bi :zh="saving?'正在导入':'导入 '+selected.length+' 个词'" :fr="saving?'Importation…':'Importer '+selected.length+' mots'" small/></button></view></view></view></template>
<script setup>
import {computed,ref,watch} from 'vue';import ConjugationOptions from './ConjugationOptions.vue';import {defaultPlan,isIrregularLemma} from '../conjugation/catalog.js';import Bi from './Bi.vue';import Icon from './Icon.vue';import {splitWords,makeLookup} from '../domain/quick-import.js';
const props=defineProps({library:Array});const emit=defineEmits(['close','import']);const input=ref(''),results=ref([]),error=ref(''),importedNotice=ref(''),importedLessons=ref([]),loading=ref(false),saving=ref(false);let dictionary;watch(input,()=>{results.value=[];error.value='';importedNotice.value='';importedLessons.value=[];});
const importedLabel=computed(()=>"单词已导入"+(importedLessons.value.length?' · '+importedLessons.value.join('、'):'')),importedLabelFr=computed(()=>"Mots importés"+(importedLessons.value.length?' · '+importedLessons.value.join(', '):''));
function rememberImports(lessons=[]){importedNotice.value='done';importedLessons.value=[...new Set([...importedLessons.value,...lessons])].sort((a,b)=>a.localeCompare(b,undefined,{numeric:true}));}
const conjugationPlan=ref(defaultPlan());
const selected=computed(()=>results.value.flatMap(r=>r.options.filter(o=>o.id===r.selected)));
async function lookup(){document.activeElement?.blur();const words=splitWords(input.value);if(words.length>200){error.value='每次最多 200 个词 / 200 mots maximum.';return;}loading.value=true;error.value='';try{if(!dictionary){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),45000);let r;try{r=await fetch(new URL('static/lexicon/french.json',document.baseURI),{signal:controller.signal});}finally{clearTimeout(timer);}if(!r.ok)throw Error();const data=await r.json();if(data.schema!==1||!Array.isArray(data.entries)||!data.entries.length)throw Error();dictionary=data.entries;}const resolve=makeLookup(dictionary,props.library),matched=[];results.value=[];for(let i=0;i<words.length;i++){const row=resolve(words[i]);if(row.options.length===1&&row.kind!=='typo')matched.push(row.options[0]);else{row.selected='';results.value.push(row);}if(i%8===0)await new Promise(r=>setTimeout(r,0));}if(matched.length){saving.value=true;emit('import',matched.map(e=>({...e,conjugationPlan:conjugationPlan.value})),(success,lessons)=>{saving.value=false;if(success)rememberImports(lessons);},true);}}catch{error.value='词库暂时无法读取，请重试 / Dictionnaire indisponible.';}finally{loading.value=false;}}
function submit(){if(!selected.value.length||saving.value)return;saving.value=true;emit('import',selected.value.map(e=>({...e,conjugationPlan:conjugationPlan.value})),(success,lessons)=>{saving.value=false;if(success){rememberImports(lessons);results.value=results.value.filter(r=>!r.selected);}},true);}
</script>
<style scoped>
.quick-import-body{flex:1;min-height:0;overflow-y:auto;padding:8px 2px 12px;display:flex;flex-direction:column;gap:14px}.quick-import-input{width:100%;height:auto;min-height:88px;max-width:100%;overflow-wrap:anywhere;word-break:break-word;white-space:pre-wrap;flex:none;box-sizing:border-box;padding:15px;border:1px solid #dce4f1;background:#ffffffd9;border-radius:20px;box-shadow:0 5px 20px #7085a407;font:16px/1.6 Georgia,serif;color:#49617f}.quick-import-body>.button{flex:none;align-self:flex-start}.quick-import-results{display:flex;flex-direction:column;gap:12px}.quick-import-row{padding:16px;display:flex;flex-direction:column;gap:9px}.quick-import-row>text{font-size:12px;color:#94a5bc}.quick-word-choice{display:flex;align-items:center;gap:12px;padding:10px;border:1px solid #d9e2ee;border-radius:12px;line-height:1.6;background:#f9fbfe}.quick-word-choice>view{flex:1;min-width:0}.quick-word-choice>view>text{display:block;overflow-wrap:anywhere}.quick-word-choice.selected{border-color:#a8bddc;background:#edf3fc}.quick-word-choice .muted{font-size:11px}.quick-word-pending{font-size:10px;color:#ae9370}.quick-import-error{font-size:12px;color:#b97780;line-height:1.7}.quick-import-page .exercise-footer{flex:none}.quick-import-page .practice-top>.bi{flex:1}.quick-import-page :deep(uni-text){line-height:1.6}
.quick-word-pronunciation{font-size:11px;color:#9aaac1;line-height:1.6}
.import-top{min-height:52px;flex:none;gap:15px}.missing-word{display:flex;align-items:center;justify-content:space-between;gap:10px}
.import-success{display:flex;align-items:center;gap:9px;color:#739d8c;font-size:11px;padding:4px 1px}
</style>
